      "codigo_refatorado": "using UnityEngine;

public class StressTestScene : MonoBehaviour
{
    // Cache de estruturas e objetos em escopo de classe para evitar alocações por frame
    [SerializeField] private int bufferSize = 1024;
    private Vector3[] positionBuffer;

    private void Awake()
    {
        // Alocação realizada apenas uma vez na inicialização
        positionBuffer = new Vector3[bufferSize];
    }

    private void Update()
    {
        // Processamento direto reutilizando a memória preexistente sem alocar novos objetos ou strings
        float deltaTime = Time.deltaTime;
        for (int i = 0; i < positionBuffer.Length; i++)
        {
            positionBuffer[i].x += deltaTime;
        }
    }
}",
      "explicacao_didatica": "Quando instanciamos objetos, arrays ou concatenamos strings dentro do Update, o Unity aloca espaço na memória Heap a cada frame. Com o tempo, essa memória enche e o sistema precisa pausar o jogo para limpar o lixo (Garbage Collection). Essa pausa gera travamentos (stuttering). A solução é mover todas as alocações para o Awake/Start e reutilizar as mesmas variáveis no Update."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Tempo elevado de processamento no script Update() (16.85ms) somado ao tempo de coleta de lixo (3.06ms no pico da chamada e até 17.94ms de GC total), elevando o tempo total de CPU para 43.79ms.",
